/* База эталонных изображений и визуальное распознавание панелей FORONE.KZ.
   Данные извлечены из CatalogNew (11).html. Модуль не заменяет QR/штрихкод,
   а работает параллельно с ним в одной камере. */
const PANEL_VISUAL_DATA = [{"code": "K01-03-22X", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "K01-110X", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "K01-135X", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "K01-136X", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "K01-140X", "series": "Marble", "img": "data:image/jpeg;base64,"}, {"code": "K01-171X", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "K01-174X", "series": "Marble", "img": "data:image/jpeg;base64,"}, {"code": "K01-176X", "series": "Marble", "img": "data:image/jpeg;base64,"}, {"code": "QK098X", "series": "Marble", "img": "data:image/jpeg;base64,"}, {"code": "QK099X", "series": "Marble", "img": "data:image/jpeg;base64,"}, {"code": "K01-120X", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "K01-124X", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "K01-127X", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "K01-133X", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "K01-212H", "series": "Artistic Pattern", "img": "data:image/jpeg;base64,"}, {"code": "K01-53H", "series": "Leather", "img": "data:image/jpeg;base64,"}, {"code": "K01-54H", "series": "Leather", "img": "data:image/jpeg;base64,"}, {"code": "K01-62H", "series": "Leather", "img": "data:image/jpeg;base64,"}, {"code": "K01-63H", "series": "Leather", "img": "data:image/jpeg;base64,"}, {"code": "K01-17N", "series": "Skin Feel", "img": "data:image/jpeg;base64,"}, {"code": "K01-18N", "series": "Skin Feel", "img": "data:image/jpeg;base64,"}, {"code": "K01-194N", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "K01-203N", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "K01-204N", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "K01-206N", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "K01-247N", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "K01-254M", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "K01-38M", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "K01-187N", "series": "Skin Feel", "img": "data:image/jpeg;base64,"}, {"code": "H093-F", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "H098-F", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "H003-H", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "H006-H", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "H198-Y", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "M/H-215Y", "series": "Marble", "img": "data:image/jpeg;base64,"}, {"code": "M/H-270Y", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "M/H-271Y", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "H091-Y", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "H072-YP", "series": "Solid", "img": "data:image/jpeg;base64,"}, {"code": "H205-YP", "series": "Solid", "img": "data:image/jpeg;base64,"}, {"code": "H234-YP", "series": "Solid", "img": "data:image/jpeg;base64,"}, {"code": "H236-YP", "series": "Solid", "img": "data:image/jpeg;base64,"}, {"code": "H241-YP", "series": "Leather", "img": "data:image/jpeg;base64,"}, {"code": "H149-PP1", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "H127-PP2", "series": "Skin Feel", "img": "data:image/jpeg;base64,"}, {"code": "M/P-001U", "series": "Artistic Pattern", "img": "data:image/jpeg;base64,"}, {"code": "M/P-100Q", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "M/P-065C", "series": "Solid", "img": "data:image/jpeg;base64,"}, {"code": "M/P-089R", "series": "Marble", "img": "data:image/jpeg;base64,"}, {"code": "M/P-092R", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "M/P-093R", "series": "Wood Grain", "img": "data:image/jpeg;base64,"}, {"code": "M/K01-HM005R", "series": "Fabric", "img": "data:image/jpeg;base64,"}, {"code": "M/Q-95V", "series": "Metal", "img": "data:image/jpeg;base64,"}, {"code": "M/Q-96V", "series": "Metal", "img": "data:image/jpeg;base64,"}];

window.PanelVisualMatcher = (() => {
  const LIGHT_VARIANTS = [[1,1,1],[0.8,0.8,0.8],[1.2,1.2,1.2],[1.1,1,0.88],[0.9,1,1.12]];
  let refs = null;
  let preparePromise = null;
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d', { willReadFrequently: true });

  function srgb2lab(r, g, b) {
    const f = (c) => { c /= 255; return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4); };
    const R = f(r), G = f(g), B = f(b);
    let X = (R * 0.4124 + G * 0.3576 + B * 0.1805) / 0.95047;
    let Y = R * 0.2126 + G * 0.7152 + B * 0.0722;
    let Z = (R * 0.0193 + G * 0.1192 + B * 0.9505) / 1.08883;
    const t = (v) => v > 0.008856 ? Math.cbrt(v) : 7.787 * v + 16 / 116;
    X = t(X); Y = t(Y); Z = t(Z);
    return [116 * Y - 16, 500 * (X - Y), 200 * (Y - Z)];
  }

  function trimmed(px) {
    px.sort((a, b) => a[0] - b[0]);
    const low = Math.floor(px.length * 0.12), high = Math.ceil(px.length * 0.88);
    const sample = px.slice(low, high), mean = [0, 0, 0];
    sample.forEach((value) => { mean[0] += value[0]; mean[1] += value[1]; mean[2] += value[2]; });
    mean[0] /= sample.length; mean[1] /= sample.length; mean[2] /= sample.length;
    return { mean, sample };
  }

  function features(source, sx, sy, sw, sh, gains = LIGHT_VARIANTS) {
    if (!(sw > 1 && sh > 1)) return null;
    const width = 48, height = Math.max(8, Math.round(width * sh / sw));
    canvas.width = width; canvas.height = height;
    try { ctx.drawImage(source, sx, sy, sw, sh, 0, 0, width, height); } catch (_) { return null; }
    const pixels = ctx.getImageData(0, 0, width, height).data;
    const labs = []; let texture = 0, gx = 0, gy = 0;
    gains.forEach((gain, index) => {
      const values = [];
      for (let i = 0; i < pixels.length; i += 4) values.push(srgb2lab(Math.min(255, pixels[i] * gain[0]), Math.min(255, pixels[i + 1] * gain[1]), Math.min(255, pixels[i + 2] * gain[2])));
      let lightness = null;
      if (index === 0) lightness = values.map((value) => value[0]);
      const trimmedValues = trimmed(values);
      labs.push(trimmedValues.mean);
      if (index === 0) {
        trimmedValues.sample.forEach((value) => { texture += (value[0] - trimmedValues.mean[0]) ** 2; });
        texture = Math.sqrt(texture / Math.max(1, trimmedValues.sample.length));
        for (let y = 0; y < height; y++) for (let x = 0; x < width; x++) {
          if (x < width - 1) gx += Math.abs(lightness[y * width + x + 1] - lightness[y * width + x]);
          if (y < height - 1) gy += Math.abs(lightness[(y + 1) * width + x] - lightness[y * width + x]);
        }
        gx /= Math.max(1, (width - 1) * height); gy /= Math.max(1, width * (height - 1));
      }
    });
    return { lab: labs[0], labs, texture, gradient: (gx + gy) / 2, direction: gx / (gx + gy + 1e-6) };
  }

  function colorDistance(a, b) {
    let best = Infinity;
    for (const lab of b.labs) {
      const dL = (a.lab[0] - lab[0]) * 0.5, da = a.lab[1] - lab[1], db = a.lab[2] - lab[2];
      best = Math.min(best, Math.sqrt(dL * dL + 1.3 * da * da + 1.3 * db * db));
    }
    return best;
  }

  function distance(a, b) {
    const color = colorDistance(a, b);
    const texture = (a.texture - b.texture) * 0.8;
    const gradient = (a.gradient - b.gradient);
    const direction = (a.direction - b.direction) * 6 * Math.min(1, Math.min(a.gradient, b.gradient) / 1.5);
    return Math.sqrt(color * color + texture * texture + gradient * gradient + direction * direction);
  }

  function loadImage(source) {
    return new Promise((resolve, reject) => { const image = new Image(); image.onload = () => resolve(image); image.onerror = reject; image.src = source; });
  }

  async function prepare(onProgress) {
    if (refs) return refs;
    if (preparePromise) return preparePromise;
    preparePromise = (async () => {
      const result = [];
      for (let i = 0; i < PANEL_VISUAL_DATA.length; i++) {
        const item = PANEL_VISUAL_DATA[i];
        try {
          const image = await loadImage(item.img);
          const width = image.naturalWidth, height = image.naturalHeight;
          result.push({ item, feature: features(image, width * 0.2, height * 0.2, width * 0.6, height * 0.6) });
        } catch (_) {}
        if (typeof onProgress === 'function' && (i % 4 === 0 || i === PANEL_VISUAL_DATA.length - 1)) onProgress(i + 1, PANEL_VISUAL_DATA.length);
        await new Promise((resolve) => setTimeout(resolve, 0));
      }
      refs = result.filter((entry) => entry.feature);
      return refs;
    })();
    return preparePromise;
  }

  async function match(source) {
    if (!refs || !refs.length) return null;
    const width = source.videoWidth || source.naturalWidth || source.width;
    const height = source.videoHeight || source.naturalHeight || source.height;
    if (!width || !height) return null;
    const current = features(source, width * 0.2, height * 0.2, width * 0.6, height * 0.6);
    if (!current) return null;
    const ranked = refs.map((entry) => ({ item: entry.item, distance: distance(current, entry.feature) })).sort((a, b) => a.distance - b.distance).slice(0, 3);
    const best = ranked[0];
    if (!best) return null;
    const confidence = Math.max(1, Math.min(99, Math.round(100 * Math.exp(-best.distance / 25))));
    return { ...best.item, confidence, alternatives: ranked.slice(1).map((entry) => ({ ...entry.item, confidence: Math.max(1, Math.min(99, Math.round(100 * Math.exp(-entry.distance / 25)))) })) };
  }

  return { data: PANEL_VISUAL_DATA, prepare, match, get ready() { return Boolean(refs); } };
})();
